INSERT INTO faqs (question, answer, sort_order, is_published) VALUES ('Apa model OpenAI terbaru saat ini?', 'Untuk lini produksi aktif yang stabil secara publik, model penalaran terbaru adalah o3-mini (rilis akhir Januari 2025) dan model penalaran penuh o1 (Desember 2024), berdampingan dengan lini flagship multimodal GPT-4o. Di lini riset frontier, OpenAI mengeksplorasi arsitektur agen generasi berikutnya seperti GPT-6 Astra.', 1, TRUE);
INSERT INTO faqs (question, answer, sort_order, is_published) VALUES ('Apa model OpenAI yang paling kuat untuk tugas umum dan penalaran?', 'Untuk penalaran mendalam, sains (STEM), dan logika kritis, o1 (Full) adalah model dengan performa tolok ukur tertinggi di dunia. Sementara untuk tugas teks dan visi serbaguna dengan kecepatan tinggi, GPT-4o adalah model terkuat yang paling seimbang.', 2, TRUE);
INSERT INTO faqs (question, answer, sort_order, is_published) VALUES ('Apa model OpenAI yang paling murah untuk API?', 'GPT-4o mini adalah model teks & visi termurah dengan harga hanya $0.15 per 1 juta token input dan $0.60 per 1 juta token output (dengan diskon prompt caching menjadi $0.075 per 1M token). Untuk model embedding pencarian, text-embedding-3-small bahkan lebih murah lagi di $0.02 per 1M token.', 3, TRUE);
INSERT INTO faqs (question, answer, sort_order, is_published) VALUES ('Apa itu context window pada model OpenAI?', 'Context window adalah batas total memori kerja gabungan teks input (instruksi, dokumen, riwayat chat) dan output yang dapat diproses model dalam satu kali panggilan. Model modern seperti GPT-4o memiliki konteks 128.000 token (~96.000 kata), sedangkan o3-mini dan o1 memiliki konteks 200.000 token (~150.000 kata).', 4, TRUE);
INSERT INTO faqs (question, answer, sort_order, is_published) VALUES ('Apa perbedaan mendasar antara model GPT dan Reasoning Model (o-series)?', 'Model GPT konvensional (seperti GPT-4o) memprediksi kata berikutnya secara instan dan intuitif. Sedangkan Reasoning Model (o1 dan o3-mini) menggunakan Reinforcement Learning untuk menghasilkan rantai pemikiran tersembunyi (Chain of Thought) selama beberapa detik sebelum menjawab, secara dramatis meminimalkan kesalahan logika dan halusinasi matematika/coding.', 5, TRUE);
INSERT INTO faqs (question, answer, sort_order, is_published) VALUES ('Apa itu model status Deprecated dan apakah masih bisa digunakan?', 'Model Deprecated adalah model lama yang secara resmi digantikan oleh model baru yang lebih baik (contoh: GPT-3.5 Turbo digantikan oleh GPT-4o mini). Model ini biasanya masih bisa dipanggil sementara waktu, namun pengembang sangat disarankan segera bermigrasi sebelum tanggal shutdown resmi (menjadi Retired).', 6, TRUE);
INSERT INTO faqs (question, answer, sort_order, is_published) VALUES ('Apakah model di ChatGPT sama persis dengan model di OpenAI API?', 'Tidak selalu identik. Model di ChatGPT telah disetel secara khusus (system prompt, batas guardrails, antarmuka web, web browsing default) untuk kenyamanan pengguna umum. Sementara di OpenAI API, pengembang mendapatkan akses kontrol langsung tanpa filter kepribadian tambahan, parameter teknis (temperature, top_p, reasoning_effort, structured outputs), serta harga murni berbasis token.', 7, TRUE);

